// Roboto (Vietnamese subset, weights 400/700), embedded as base64 data URLs
// so @react-pdf/renderer can load them without touching the filesystem at
// runtime — Next.js standalone output (next.config.js) does not trace
// arbitrary fs.readFileSync paths, but a plain string constant is always
// part of the JS bundle.
//
// Source: Roboto-Regular-vietnamese.woff / Roboto-Bold-vietnamese.woff in
// this same folder, fetched from Google Fonts (Apache 2.0) with the
// "vietnamese" subset. To regenerate after changing those files:
//   node -e 'const fs=require("fs");
//     const reg=fs.readFileSync("Roboto-Regular-vietnamese.woff").toString("base64");
//     const bold=fs.readFileSync("Roboto-Bold-vietnamese.woff").toString("base64");
//     fs.writeFileSync("robotoFontData.ts",
//       `export const ROBOTO_REGULAR_VIETNAMESE_DATA_URL =\n  "data:font/woff;base64,${reg}";\nexport const ROBOTO_BOLD_VIETNAMESE_DATA_URL =\n  "data:font/woff;base64,${bold}";\n`);'
export const ROBOTO_REGULAR_VIETNAMESE_DATA_URL =
  "data:font/woff;base64,";
export const ROBOTO_BOLD_VIETNAMESE_DATA_URL =
  "data:font/woff;base64,";
